using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using CAP_Core.Update;
using CAP_DataAccess.Updates;
using Shouldly;

namespace UnitTests.Update;

public sealed class ReleaseSigningInteropTests
{
    [Fact]
    public void PythonPublisherEnvelope_VerifiesAllSevenArtifactsWithDotNet()
    {
        // Generated by scripts.release.sign_manifest with a disposable in-memory key.
        // Only its public key and signed envelope are embedded; this key is never trusted in production.
        using var stream = typeof(ReleaseSigningInteropTests).Assembly
            .GetManifestResourceStream("Lunima.Tests.PythonSignedRelease.json")!;
        using var fixture = JsonDocument.Parse(stream);
        var verifier = new ReleaseManifestVerifier(new Dictionary<string, string>
        {
            ["python-test-only"] = fixture.RootElement.GetProperty("publicKey").GetString()!
        });
        var envelope = Encoding.UTF8.GetBytes(fixture.RootElement.GetProperty("envelope").GetRawText());
        (string Name, string Rid)[] assets =
        [
            ("Lunima-Setup-2.3.4.msi", "win-x64"),
            ("Lunima-2.3.4-win-x64.zip", "win-x64"),
            ("Lunima-2.3.4-linux-x64.tar.gz", "linux-x64"),
            ("Lunima-2.3.4-osx-arm64.dmg", "osx-arm64"),
            ("Lunima-2.3.4-osx-x64.dmg", "osx-x64"),
            ("Lunima-2.3.4-osx-arm64.zip", "osx-arm64"),
            ("Lunima-2.3.4-osx-x64.zip", "osx-x64")
        ];
        foreach (var (name, rid) in assets)
        {
            var artifact = verifier.Verify(envelope, "v2.3.4", new SemanticVersion(1, 0, 0), rid, name);
            artifact.SourceCommit.ShouldBe(new string('a', 40));
            artifact.Size.ShouldBe(Encoding.UTF8.GetByteCount(name));
            artifact.Sha256.ShouldBe(Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(name))).ToLowerInvariant());
        }
    }

    [Fact]
    public void EmbeddedPublisherRegistry_MatchesTheCheckedInResource()
    {
        using var stream = typeof(ReleasePublisherKeys).Assembly
            .GetManifestResourceStream("Lunima.Updates.PublisherKeys.json")!;
        var expected = JsonSerializer.Deserialize<Dictionary<string, string>>(stream)!;
        ReleasePublisherKeys.All.Count.ShouldBe(expected.Count);
        foreach (var (id, pem) in expected) ReleasePublisherKeys.All[id].ShouldBe(pem);
    }
}
